    <style>
        :root{color-scheme:dark;--gold:#ffd54a;--ink:#07111f;--panel:rgba(13,25,43,.78);--muted:#9aa9bd;--border:rgba(255,213,74,.2)}*{box-sizing:border-box}body{margin:0;min-height:100vh;display:grid;place-items:center;padding:24px;background:radial-gradient(circle at 10% 0,#273b62 0,transparent 30%),radial-gradient(circle at 90% 100%,#503717 0,transparent 30%),linear-gradient(135deg,#040914,#0a1728 55%,#050914);font-family:Poppins,system-ui,sans-serif;color:#f8fafc}.orb{position:fixed;border-radius:50%;filter:blur(1px);opacity:.25;pointer-events:none;animation:float 12s ease-in-out infinite}.orb.one{width:220px;height:220px;background:#ffd54a;top:8%;left:8%}.orb.two{width:300px;height:300px;background:#295cae;right:5%;bottom:5%;animation-delay:-5s}@keyframes float{50%{transform:translateY(25px) translateX(12px)}}.shell{width:min(100%,440px);position:relative}.brand{text-align:center;margin-bottom:24px}.crown{width:58px;height:58px;margin:auto auto 12px;display:grid;place-items:center;border-radius:18px;color:#1c1605;background:linear-gradient(135deg,#ffe98c,#d49b18);font-size:25px;box-shadow:0 10px 35px rgba(255,213,74,.25)}h1{font-size:26px;letter-spacing:-.8px;margin:0}.brand p{margin:4px 0 0;color:var(--gold);font-size:11px;font-weight:700;letter-spacing:.2em}.card{background:var(--panel);border:1px solid var(--border);padding:32px;border-radius:24px;box-shadow:0 28px 70px rgba(0,0,0,.4);backdrop-filter:blur(18px)}.intro h2{margin:0;font-size:20px}.intro p{margin:6px 0 24px;color:var(--muted);font-size:13px}.alert{display:flex;gap:10px;padding:12px;border-radius:12px;margin-bottom:17px;font-size:12px;border:1px solid}.alert.error{color:#fecdd3;background:rgba(251,113,133,.1);border-color:rgba(251,113,133,.28)}.alert.success{color:#bbf7d0;background:rgba(52,211,153,.1);border-color:rgba(52,211,153,.28)}label{display:block;font-size:12px;font-weight:600;margin:16px 0 7px}.field{position:relative}.field i{position:absolute;left:14px;top:50%;transform:translateY(-50%);color:var(--gold);font-size:13px}.field input{width:100%;padding:13px 43px;border-radius:12px;border:1px solid rgba(148,163,184,.22);background:rgba(2,8,23,.6);color:#fff;font:inherit;font-size:13px;outline:0;transition:.2s}.field input:focus{border-color:var(--gold);box-shadow:0 0 0 3px rgba(255,213,74,.12)}.toggle{position:absolute;right:7px;top:7px;border:0;background:transparent;color:var(--muted);cursor:pointer;width:34px;height:34px;border-radius:8px}.toggle:hover,.toggle:focus-visible{color:var(--gold);background:rgba(255,255,255,.06)}.submit{width:100%;margin-top:24px;border:0;border-radius:12px;padding:14px;background:linear-gradient(135deg,#ffe27a,#c98a10);color:#191305;font:700 13px Poppins,sans-serif;letter-spacing:.04em;cursor:pointer;transition:.2s}.submit:hover{transform:translateY(-2px);box-shadow:0 12px 26px rgba(255,213,74,.22)}.submit:disabled{opacity:.7;cursor:wait;transform:none}.back{display:block;text-align:center;margin:20px 0 0;color:var(--muted);font-size:12px;text-decoration:none}.back:hover{color:var(--gold)}.notice{text-align:center;color:var(--muted);font-size:10px;margin-top:19px}@media(max-width:480px){body{padding:16px}.card{padding:24px 20px;border-radius:20px}}
    </style>
</head>
<body>
<div class="orb one"></div><div class="orb two"></div>
<main class="shell"><div class="brand"><div class="crown"><i class="fas fa-crown"></i></div><h1>SMART<span style="color:var(--gold)">BASKET</span></h1><p>ADMIN CONTROL CENTER</p></div><section class="card" aria-labelledby="login-title"><div class="intro"><h2 id="login-title">Secure administrator sign in</h2><p>Use your dedicated administrator account. MFA is requested when enabled.</p></div>
