<label for="email">Administrator email</label><div class="field"><i class="fas fa-envelope"></i><input id="email" name="email" type="email" value="{{ old('email') }}" autocomplete="email" required autofocus aria-describedby="email-error"> </div>@error('email')<small id="email-error" style="color:#fda4af">{{ $message }}</small>@enderror
<label for="password">Password</label><div class="field"><i class="fas fa-lock"></i><input id="password" name="password" type="password" autocomplete="current-password" required><button class="toggle" type="button" aria-label="Show password" aria-pressed="false" id="passwordToggle"><i class="fas fa-eye"></i></button></div>@error('password')<small style="color:#fda4af">{{ $message }}</small>@enderror
<button class="submit" type="submit" id="loginButton"><i class="fas fa-shield-halved"></i> Secure Admin Login</button></form><a class="back" href="{{ url('/') }}"><i class="fas fa-arrow-left"></i> Return to SmartBasket</a></section><p class="notice"><i class="fas fa-lock"></i> Restricted access is monitored and audited.</p></main>
<script>const toggle=document.getElementById('passwordToggle'),password=document.getElementById('password');toggle.addEventListener('click',()=>{const reveal=password.type==='password';password.type=reveal?'text':'password';toggle.setAttribute('aria-pressed',String(reveal));toggle.setAttribute('aria-label',reveal?'Hide password':'Show password');toggle.firstElementChild.className=reveal?'fas fa-eye-slash':'fas fa-eye'});document.getElementById('adminLoginForm').addEventListener('submit',()=>{const button=document.getElementById('loginButton');button.disabled=true;button.innerHTML='<i class="fas fa-spinner fa-spin"></i> Signing in…'});</script>
</body></html>
